contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We accept an input amount to forward to c.play()
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure we have enough ETH to forward if needed
        require(address(this).balance >= amount);

        // observe initial public values
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint contract_balance_before = address(c).balance;

        // perform the state-changing call and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe final public values
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint contract_balance_after = address(c).balance;

        // General rule:
        // 1) The bank public address must never change as a result of play()
        // 2) If the call did not revert, the pot increases by at most amount (never grows by more than the ticket sent)
        //    and the change in contract balance is consistent with the pot change (no unexpected extra creation of value).
        assert(
            bank_before == bank_after
            && (
                reverted
                || (
                    // if not reverted: pot_after - pot_before <= amount
                    pot_after >= pot_before && pot_after - pot_before <= amount
                    // and change in contract balance equals pot change (since only pot and transfers change c.balance)
                    && contract_balance_after + 0 == contract_balance_before + (pot_after - pot_before)
                )
            )
        );
    }

    // accept ETH when contract pays out
    receive() external payable {}
}

