// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address bank_before;
        try c.bank() returns (address __r) { bank_before = __r; } catch { return; }
        uint256 pot_before;
        try c.pot() returns (uint256 __r) { pot_before = __r; } catch { return; }
        uint contract_balance_before = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bank_after;
        try c.bank() returns (address __r) { bank_after = __r; } catch { return; }
        uint256 pot_after;
        try c.pot() returns (uint256 __r) { pot_after = __r; } catch { return; }
        uint contract_balance_after = address(c).balance;
        assertTrue(bank_before == bank_after
            && (
                reverted
                || (
                    // if not reverted: pot_after - pot_before <= amount
                    pot_after >= pot_before && pot_after - pot_before <= amount
                    // and change in contract balance equals pot change (since only pot and transfers change c.balance)
                    && contract_balance_after + 0 == contract_balance_before + (pot_after - pot_before)
                )
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
